methods.news:
export class WhatsNew {
  constructor(menus) {
    this.M = menus;
    this.el = null;
    this.page = 0;
    this._t = 0;
    this._tweens = [];
    this._raf = 0;
    this._busy = false;
  }

  get open() { return !!this.el; }

  /** menus.js: the main screen just mounted. Opens once the menu's own wipe has settled. */
  maybeShow() {
    if (this.el) return;
    const g = gate();
    if (!g || (g !== 'force' && newsSeen())) return;
    if (g === 'force' && this._shownForce) return;
    clearTimeout(this._t); this._cancelHeroWait(); this._heroDone = null;
    // fetch both hero renders now: the card waits (briefly) for its image instead of opening on an empty frame
    if (!this._pre) this._pre = PAGES.map((P) => { const im = new Image(); im.decoding = 'async'; im.src = art(P.img); return im; });
    this._waitFrom = performance.now();
    this._t = setTimeout(() => this._tryOpen(0), 700);
  }
  _tryOpen(n) {
    const M = this.M;
    if (this.el || M.current !== 'main' || !M._scr || G.mode === 'match') { this._cancelHeroWait(); this._pre = this._heroDone = null; return; }
    if (M._modal || (M.wipe && M.wipe.busy) || M._starting) {
      if (n < 60) this._t = setTimeout(() => this._tryOpen(n + 1), 150);
      return;
    }
    const hero = this._pre && this._pre[0];
    if (hero && hero !== this._heroDone && !hero.complete && performance.now() - this._waitFrom < 4000) {
      if (!this._heroWait) {
        const finish = () => {
          if (this._heroWait !== cleanup) return;
          this._heroDone = hero; this._cancelHeroWait(); this._tryOpen(n);
        };
        const cleanup = () => {
          hero.removeEventListener('load', finish); hero.removeEventListener('error', finish);
          clearTimeout(timer); this._heroWait = null;
        };
        const timer = setTimeout(finish, Math.max(0, 4000 - (performance.now() - this._waitFrom)));
        this._heroWait = cleanup;
        hero.addEventListener('load', finish); hero.addEventListener('error', finish);
        if (hero.complete) finish();
      }
      return;
    }
    this.show();
  }

  _cancelHeroWait() { if (this._heroWait) this._heroWait(); }

  // ================================================================ build
  show() {
    const M = this.M;
    if (this.el || !M._scr) return;
    if (gate() === 'force') this._shownForce = true;
    markSeen();   // shown once: even a reload mid-sequence won't bring it back
    this.reduced = prefersReducedMotion();
    this.page = 0;
    this.inkHost = h('div', { class: 'iw-news__inks' });
    this.card = h('div', { class: 'iw-news__card' });
    this.confetti = h('div', { class: 'iw-news__confetti' });
    const el = this.el = h('div', { class: 'iw-news' + (this.reduced ? ' is-reduced' : ''), role: 'dialog', 'aria-modal': 'true', 'aria-label': 'What’s new' },
      h('div', { class: 'iw-news__dim' }), this.inkHost, this.confetti, h('div', { class: 'iw-news__stage' }, this.card));
    el._onBack = () => this.close('back');
    el.dataset.keys = '1';
    M._scr.el.appendChild(el);
    M._modalPrev = M._focus;
    M._modal = el;
    M._sfx('splat_big');
    this._render(0, true);
    this._cancelHeroWait(); clearTimeout(this._t); this._t = 0; this._pre = this._heroDone = null;
    const r = el.getBoundingClientRect();
    this._ink(PAGES[0].tone, r.width * 0.5, r.height * 0.52, 0.62, false);
  }

  _render(i, first) {
    const M = this.M, P = PAGES[i];
    this.page = i;
    this.el.dataset.page = P.id;
    this.el.style.setProperty('--nc', `var(--${P.tone})`);
    this.el.style.setProperty('--nc-light', `var(--${P.tone}-light)`);
    this.el.style.setProperty('--nc-dark', `var(--${P.tone}-dark)`);
    this.el.style.setProperty('--nc-ink', `var(--${P.tone}-ink)`);
    this.el.style.setProperty('--nc-rgb', `var(--${P.tone}-rgb)`);
    // hero: the render, framed like a ticket, taped to the card
    const img = h('img', { class: 'iw-news__img', alt: '', draggable: 'false' });
    const frame = h('div', { class: 'iw-news__frame' }, img, h('i', { class: 'iw-news__glare' }));
    img.addEventListener('load', () => frame.classList.add('is-loaded'), { once: true });
    img.addEventListener('error', () => {
      img.remove();
      frame.classList.add('is-loaded', 'is-fallback');
      frame.prepend(h('div', { class: 'iw-news__fb', html: P.fallback ? P.fallback() : `<span class="iw-news__fbsquid">${SQUID}</span>` }));
    }, { once: true });
    img.src = art(P.img);
    const hero = h('div', { class: 'iw-news__hero' },
      h('span', { class: 'iw-news__herosplat', html: splatSVG({ seed: 17 + i * 11, fill: 'var(--nc)', r: 58, arms: 9, drops: 5 }) }),
      frame,
      h('i', { class: 'iw-news__tapebit is-tl' }), h('i', { class: 'iw-news__tapebit is-br' }),
      P.stamp ? h('span', { class: `iw-news__stamp ${P.stamp.cls}` }, P.stamp.text) : null,
      P.tape ? h('span', { class: 'iw-news__tape' }, h('span', null, P.tape)) : null);
    // body
    const list = h('ul', { class: 'iw-news__list' }, P.bullets.map(([ic, b, t, thumb], k) => {
      const li = h('li', { style: { '--i': k } }, h('i', { class: 'iw-news__bico', html: ic }), h('span', null, h('b', null, b), ' — ', t));
      if (thumb) {
        const im = h('img', { class: 'iw-news__thumb', alt: '', draggable: 'false' });
        im.addEventListener('error', () => im.remove(), { once: true });
        im.src = art(thumb);
        li.appendChild(im);
      }
      return li;
    }));
    const btns = [];
    if (i === 0) {
      const go = M._btn({ id: 'news-continue', label: 'CONTINUE', cls: 'iw-btn--primary iw-btn--wide iw-news__go', sound: 'ui_confirm', accept: () => this.next() });
      go.append(h('span', { class: 'iw-news__chev', html: GLYPHS.next }));
      const skip = M._btn({ id: 'news-skip', label: 'Skip', cls: 'iw-btn--small iw-btn--ghost iw-news__skip', sound: 'ui_back', accept: () => this.close('skip') });
      skip.appendChild(h('span', { class: 'iw-news__skipkey' }, M._hint('Esc', 'B')));
      btns.push(go, skip);
    } else {
      const go = M._btn({ id: 'news-try', label: 'TRY IT', icon: GLYPHS.play, cls: 'iw-btn--primary iw-btn--wide iw-news__go', sound: 'ui_confirm', accept: () => this.close('try') });
      const later = M._btn({ id: 'news-later', label: 'LATER', cls: 'iw-btn--wide iw-btn--ghost iw-news__later', sound: 'ui_back', accept: () => this.close('later') });
      btns.push(go, later);
    }
    btns[0].appendChild(h('span', { class: 'iw-news__key' }, M._hint('Enter', 'A')));
    const dots = h('span', { class: 'iw-news__dots' }, PAGES.map((_, k) => h('i', { class: k === i ? 'is-on' : '' })));
    const body = h('div', { class: 'iw-news__body' },
      h('div', { class: 'iw-news__kicker' }, h('i', { html: GLYPHS.sparkle }), P.kicker),
      h('div', { class: 'iw-news__title iw-display' + (P.title.length === 1 ? ' is-one' : '') }, P.title.map((t, k) => h('span', { style: { '--i': k } }, t))),
      h('p', { class: 'iw-news__lede' }, P.lede),
      list,
      h('div', { class: 'iw-news__btns' }, btns),
      h('div', { class: 'iw-news__foot' }, dots, h('span', { class: 'iw-news__count' }, `${i + 1} / ${PAGES.length}`)));
    // WebKit can shift this overflowing card between pointerdown and pointerup.
    // Touch events retain the original target; activate only a tap, never a scroll.
    for (const button of btns) {
      let start = null;
      button.addEventListener('touchstart', (e) => { start = e.touches.length === 1 ? e.touches[0] : null; }, { passive: true });
      button.addEventListener('touchmove', (e) => {
        const point = start && findTouchById(e.touches, start.identifier);
        if (!point || Math.hypot(point.clientX - start.clientX, point.clientY - start.clientY) > 10) start = null;
      }, { passive: true });
      button.addEventListener('touchcancel', () => { start = null; }, { passive: true });
      button.addEventListener('touchend', (e) => {
        const point = start && findTouchById(e.changedTouches, start.identifier);
        const tap = point && Math.hypot(point.clientX - start.clientX, point.clientY - start.clientY) <= 10;
        start = null;
        if (!tap) return;
        e.preventDefault(); button.classList.remove('is-down'); button.click();
      }, { passive: false });
    }
    this.card.innerHTML = '';
    this.card.append(hero, body);
    restartAnim(this.card, first ? 'is-in' : 'is-swap');
    M._setFocus(btns[0], { snap: true });
    if (!this.reduced) {
      this._confetti();
      setTimeout(() => { if (this.el && this.el.isConnected) inkBurst(this.M._scr.el, { ...this._center(body.querySelector('.iw-news__title')), color: 'var(--nc)', count: 14, dist: 12, size: 1.5, ring: true }); }, first ? 520 : 260);
    }
  }
  _center(node) {
    if (!node) return { x: innerWidth / 2, y: innerHeight / 2 };
    const r = node.getBoundingClientRect();
    return { x: r.left + r.width * 0.35, y: r.top + r.height / 2 };
  }

  _confetti() {
    const host = this.confetti;
    host.innerHTML = '';
    for (let i = 0; i < 34; i++) {
      const x = ((i * 0.618034 + 0.07) % 1) * 100;
      host.appendChild(h('i', { style: {
        left: `${x.toFixed(1)}%`, '--c': CONFETTI[i % CONFETTI.length], '--d': `${(0.05 + ((i * 0.37) % 1) * 0.5).toFixed(2)}s`,
        '--t': `${(1.5 + ((i * 0.53) % 1) * 1.1).toFixed(2)}s`, '--r': `${Math.round(((i * 0.71) % 1) * 720 - 360)}deg`,
        '--x': `${(((i * 0.29) % 1) - 0.5) * 12}vw`, '--w': `${(0.5 + ((i * 0.43) % 1) * 0.7).toFixed(2)}`, '--k': i % 3 ? '0' : '1',
      } }));
    }
    restartAnim(host, 'is-on');
  }

  // ================================================================ ink wipes (splat clip-path grown by JS)
  /** A full-screen layer of `tone` ink revealed by a splat growing from (x, y). */
  _ink(tone, x, y, dur, fromPrev) {
    const layer = h('div', { class: `iw-news__ink is-${tone}` }, h('i', { class: 'iw-news__halftone' }));
    this.inkHost.appendChild(layer);
    const W = this.el.clientWidth || innerWidth, H = this.el.clientHeight || innerHeight;
    const R = splatCover(x, y, W, H), seed = 7 + this.inkHost.childElementCount * 13;
    if (this.reduced) { layer.style.clipPath = ''; layer.classList.add('is-fade'); this._pruneInks(layer); return layer; }
    const clip = createSplatClip(seed);
    layer.style.clipPath = clip(x, y, 0.01);
    this._tween(dur, (k) => { layer.style.clipPath = clip(x, y, R * easeOutCubic(k)); }, () => { layer.style.clipPath = ''; if (fromPrev) this._pruneInks(layer); });
    layer._splat = { x, y, R, seed };
    return layer;
  }
  _pruneInks(keep) { for (const n of [...this.inkHost.children]) if (n !== keep) n.remove(); }

  _tween(dur, step, done) {
    const o = { t: 0, dur: Math.max(0.01, dur), step, done };
    this._tweens.push(o);
    step(0);
    if (!this._raf) { this._last = performance.now(); this._raf = requestAnimationFrame((t) => this._tick(t)); }
    return o;
  }
  _tick(t) {
    const dt = Math.min(0.1, (t - this._last) / 1000) * (this.M.timeScale ?? 1);   // slow frames still finish the wipe on time
    this._last = t;
    for (let i = this._tweens.length - 1; i >= 0; i--) {
      const o = this._tweens[i];
      o.t += dt;
      const k = clamp(o.t / o.dur);
      safeCall(o.step, k);
      if (k >= 1) { this._tweens.splice(i, 1); if (o.done) safeCall(o.done); }
    }
    this._raf = this._tweens.length ? requestAnimationFrame((tt) => this._tick(tt)) : 0;
  }

  // ================================================================ flow
  next() {
    if (!this.el || this._busy || this.page >= PAGES.length - 1) return;
    this._busy = true;
    const btn = this.card.querySelector('.iw-news__go');
    const c = btn ? this._center(btn) : { x: innerWidth * 0.7, y: innerHeight * 0.7 };
    const r = this.el.getBoundingClientRect();
    this.card.classList.add('is-out');
    this.M._sfx('splat_big', 0.05);
    this._ink(PAGES[1].tone, c.x - r.left, c.y - r.top, this.reduced ? 0.01 : 0.55, true);
    this._nextTimer = setTimeout(() => { this._nextTimer = 0; if (!this.el) return; this.card.classList.remove('is-out'); this._render(1, false); this._busy = false; }, this.reduced ? 0 : 300);
  }

  /** how: 'skip' | 'later' | 'back' | 'try' */
  close(how = 'later') {
    const M = this.M, el = this.el;
    if (!el || el._closing) return;
    el._closing = true;
    clearTimeout(this._t);
    if (M._modal === el) M._modal = null;
    el.classList.add('is-leaving');
    this.card.classList.add('is-out');
    if (how === 'back') M._sfx('ui_back');
    const finish = () => { el.remove(); if (this.el === el) { this.el = null; this._pre = null; } };
    if (how === 'try') { cancelAnimationFrame(this._raf); this._raf = 0; this._tweens.length = 0; finish(); this._tryBoss(); return; }
    // the splat drains back into the card's centre, the menu underneath comes back
    const last = this.inkHost.lastElementChild;
    if (!this.reduced && last && last._splat) {
      const s = last._splat, r = el.getBoundingClientRect(), cr = this.card.getBoundingClientRect();
      const x = cr.left + cr.width / 2 - r.left, y = cr.top + cr.height / 2 - r.top, R = splatCover(x, y, r.width, r.height);
      this._pruneInks(last);
      const clip = createSplatClip(s.seed + 1);
      this._tween(0.5, (k) => { last.style.clipPath = clip(x, y, Math.max(0.01, R * (1 - easeInOutCubic(k)))); }, finish);
    } else this._closeTimer = setTimeout(() => { this._closeTimer = 0; finish(); }, this.reduced ? 200 : 450);
    const prev = M._modalPrev;
    if (prev && prev.isConnected) M._setFocus(prev, { snap: true });
  }

  /** TRY IT: Play › Boss Battle stage select, with Back leading to the mode cards (boss focused). */
  _tryBoss() {
    const M = this.M;
    const st = M._setup || (M._setup = { times: {} });
    st.mode = 'boss';
    M._setSetting('lastMode', 'boss');
    M._stack = ['main', 'mode'];
    M.show('setup', { push: true });
  }

  dispose() { this._cancelHeroWait(); this._heroDone = null; this._pre = null; clearTimeout(this._t); clearTimeout(this._nextTimer); clearTimeout(this._closeTimer); this._t = this._nextTimer = this._closeTimer = 0; cancelAnimationFrame(this._raf); this._raf = 0; this._tweens.length = 0; if (this.M._modal === this.el) this.M._modal = null; if (this.el) this.el.remove(); this.el = null; this.card = this.inkHost = this.confetti = null; this._busy = false; }
}

methods.launch:
launchLobby() {
  if (this._launchP) return this._launchP;
  const s = this._scr;
  if (this.current !== 'lobby' || !s || !s.launch) return Promise.resolve();
  let fin = null;
  const p = new Promise((res) => { let done = false; fin = () => { if (!done) { done = true; res(); } }; });
  this._launchP = p;
  s.launch(fin);
  setTimeout(fin, 7000);
  p.then(() => { if (this._launchP === p) this._launchP = null; });
  return p;
}

methods.cursor:
_updateCursor(dt) {
  const C = this._cur, f = this._focus, layout = menuLayoutSample(this, f);
  // hide while the focused element is still popping in (staggered entrance keeps it transparent);
  // elements with their own focus ring (tilting cards) opt out with data-cur="own"
  // on touch, rows and tabs show their own selected state (tint / pill): no console-style ring after a tap
  const touchOwn = this._input === 'touch' && f && (f.dataset.nav === 'row' || f.dataset.nav === 'tab');
  const want = !!(f && f.isConnected && !touchOwn && !(this._scr && this._scr.noCursor) && f.dataset.cur !== 'own' && !f.closest('.is-leaving') && parseFloat(layout.opacity(f)) > 0.6);
  if (!want) {
    if (f && f.isConnected && C.targetEl !== f) {
      const r = layout.rect(f), pad = f.dataset.curPad != null ? +f.dataset.curPad : 7;
      C.targetEl = f;
      C.x.target = r.left - pad; C.y.target = r.top - pad;
      C.w.target = r.width + pad * 2; C.h.target = r.height + pad * 2;
    }
    if (C.on) { this.cursorEl.classList.remove('is-on'); C.on = false; }
    C.snapNext = true;
    return;
  }
  const r = layout.rect(f);
  const pad = f.dataset.curPad != null ? +f.dataset.curPad : 7;
  const tx = r.left - pad, ty = r.top - pad, tw = r.width + pad * 2, th = r.height + pad * 2;
  C.targetEl = f;
  C.x.target = tx; C.y.target = ty; C.w.target = tw; C.h.target = th;
  if (C.snapNext || !C.on) { C.x.snap(tx); C.y.snap(ty); C.w.snap(tw); C.h.snap(th); C.snapNext = false; }
  else if (dt > 0) { C.x.step(dt); C.y.step(dt); C.w.step(dt); C.h.step(dt); }
  if (!C.on) { this.cursorEl.classList.add('is-on'); C.on = true; }
  const st = this.cursorEl.style;
  { const value = `translate3d(${C.x.x.toFixed(1)}px,${C.y.x.toFixed(1)}px,0)`; if (st.transform !== value) st.transform = value; }
  { const value = Math.max(0, C.w.x).toFixed(1) + 'px'; if (st.width !== value) st.width = value; }
  { const value = Math.max(0, C.h.x).toFixed(1) + 'px'; if (st.height !== value) st.height = value; }
  const rad = parseFloat(C.r) || 0;
  const rr = `${Math.round(rad + pad)}px`;
  if (st.borderRadius !== rr) st.borderRadius = rr;
  // a row scrolled part-way out of its list: cut the ring at the list edge along with the row
  let clip = '';
  const sc = f.closest('.iw-rows, .iw-ss__list');
  if (sc && sc.scrollHeight > sc.clientHeight + 1) {
    const b = layout.rect(sc);
    const ct = r.top < b.top - 0.5 ? b.top - C.y.x : 0, cb = r.bottom > b.bottom + 0.5 ? C.y.x + C.h.x - b.bottom : 0;
    if (ct > 0 || cb > 0) clip = `inset(${Math.max(0, ct).toFixed(1)}px -24px ${Math.max(0, cb).toFixed(1)}px -24px)`;
  }
  if (C.clip !== clip) { C.clip = clip; st.clipPath = clip; }
}

methods.renderer:
applySettings(settings) {
  const prevQ = this.q;
  this.settings = settings;
  this.q = effectiveQuality(settings, this.mobile);
  const shadowChanged = this.renderer.shadowMap.enabled !== (settings.shadows !== false);
  const qualityChanged = prevQ !== this.q && (!prevQ || Object.keys(prevQ).length !== Object.keys(this.q).length || Object.keys(this.q).some(key => prevQ[key] !== this.q[key]));
  if (qualityChanged) {
    this.dynScale = 1;
    this._buildComposer();
  } else if (shadowChanged) {
    // Shadows change shader defines, not HDR/post-processing target formats.
    // Preserve the composer, accumulated dynamic resolution and ScreenFX passes.
    this.renderer.shadowMap.enabled = settings.shadows !== false;
    this.renderer.shadowMap.needsUpdate = true;
  }
  if (qualityChanged || shadowChanged) {
    this.scene?.traverse((o) => { if (o.material) { const m = Array.isArray(o.material) ? o.material : [o.material]; m.forEach((mm) => (mm.needsUpdate = true)); } });
  }
  if (this.bloom) this.bloom.enabled = !!(this.q.bloom && settings.bloom);
}

methods.dots:
// dots
const ps = m.players || [];
const ca = L.ca || '#ff8a14', cb = L.cb || '#2f5bff';
for (let i = 0; i < this.mapDots.length; i++) {
  const d = this.mapDots[i], p = ps[i];
  const dk = `md${i}`;
  if (!p) { if (L[dk] !== 'x') { L[dk] = 'x'; d.style.display = 'none'; } continue; }
  const px = clamp(+p.x || 0) * bw, py = clamp(+p.y || 0) * bh;
  if (p.isSelf) { M.sx = clamp(+p.x || 0); M.sy = clamp(+p.y || 0); }
  const raw = d._mapKey || (d._mapKey = {}), self = !!p.isSelf, yaw = self ? (+p.yaw || 0) : 0, alive = p.alive !== false;
  if (raw.key === L[dk] && raw.valid && Object.is(raw.x, px) && Object.is(raw.y, py) && Object.is(raw.yaw, yaw) && raw.alive === alive && raw.self === self && raw.team === p.team) continue;
  const px1 = px.toFixed(1), py1 = py.toFixed(1);
  const key = `${px1}|${py1}|${yaw.toFixed(2)}|${p.alive === false ? 0 : 1}|${p.isSelf ? 1 : 0}|${p.team}`;
  raw.key = key; raw.valid = true; raw.x = px; raw.y = py; raw.yaw = yaw; raw.alive = alive; raw.self = self; raw.team = p.team;
  if (L[dk] === key) continue;
  const prev = L[dk] || '';
  L[dk] = key;
  if (prev === 'x' || !prev) d.style.display = '';
  const sk = `${p.isSelf ? 1 : 0}|${p.alive === false ? 0 : 1}|${p.team}`;
  if (d._sk !== sk) {
    d._sk = sk;
    d.className = 'iw-mdot' + (p.isSelf ? ' is-self' : '') + (p.alive === false ? ' is-dead' : '') + (p.team !== this._myTeam() ? ' is-enemy' : '');
    d.style.setProperty('--c', p.team !== this._myTeam() ? cb : ca);
  }
  d.style.transform = `translate3d(${px1}px,${py1}px,0) rotate(${p.isSelf ? (+p.yaw || 0).toFixed(3) : 0}rad)`;
}

methods.beacons:
for (let i = 0; i < tg.length; i++) {
  const el = this.beacons[i], b = tg[i], p = P[i];
  const key = b ? `${p.x.toFixed(0)}|${p.y.toFixed(0)}|${p.ox.toFixed(0)}|${p.oy.toFixed(0)}|${b.ok ? 1 : 0}|${b.dead ? 1 : 0}|${M.hover === i ? 1 : 0}|${canJump ? 1 : 0}|${b.name}` : 'x';
  this._updLegendRow(i, b, canJump);
  if (el._key === key) continue;
  el._key = key;
  if (!b) { el.style.display = 'none'; continue; }
  el.style.display = '';
  el.style.transform = `translate3d(${p.x.toFixed(1)}px,${p.y.toFixed(1)}px,0)`;
  const sx = p.ox - p.x, sy = p.oy - p.y, sl = Math.hypot(sx, sy);
  const stem = el.firstChild;
