      const wallGap = this.lastWall === null ? 0 : (wall - this.lastWall) / 1000;
      const gap = !Number.isFinite(dt) || dt < 0 || dt > MAX_PLATFORM_GAP || wallGap > MAX_PLATFORM_GAP;
