    }
    if(ring.parentNode!==host)host.appendChild(ring);
    // The native pass wrote viewport geometry (and a viewport clip for
    // lists). Convert to the scroller's content box; its own overflow clip
    // replaces the computed one. Keep the ring inside the host horizontally
    // so a full-width row is not cut along its sides.
    const C=m._cur,b=m._queueLayoutSample?.rect(host)||host.getBoundingClientRect();
    const ox=b.left+host.clientLeft-host.scrollLeft,oy=b.top+host.clientTop-host.scrollTop;
    let x=C.x.x-ox,w=Math.max(0,C.w.x);
    const lo=host.scrollLeft+1,hi=host.scrollLeft+host.clientWidth-1;
    if(x<lo){w-=lo-x;x=lo;}
    if(x+w>hi)w=Math.max(0,hi-x);
    const st=ring.style;
    const transform=`translate3d(${x.toFixed(1)}px,${(C.y.x-oy).toFixed(1)}px,0)`,width=w.toFixed(1)+'px';
    if(st.transform!==transform)st.transform=transform;
    if(st.width!==width)st.width=width;
    if(C.clip){C.clip='';st.clipPath='';}
  }
  if(cursor)P._updateCursor=function(dt){frameTick(this);return place(this,dt);};
  // Logical selection, geometric target and the painted ring all commit in
  // this task, including touch's own-row highlight and deselection.
  // toast() inserts its stack before the ring; the ring must be home first.
  const toast=P.toast;
  if(toast&&cursor)P.toast=function(...args){home(this);return toast.apply(this,args);};
  if(focus&&cursor)P._setFocus=function(...args){
    const old=this._focus,result=focus.apply(this,args);
    if(old!==this._focus)place(this,0);
    return result;
  };
  if(inputMode&&cursor)P.setInputMode=function(...args){
    const old=this._input,result=inputMode.apply(this,args);
    // Input-mode callbacks can reflow the same focused element.
    if(old!==this._input){this._cur.targetEl=null;place(this,0);}
    return result;
  };
  // Screen ownership of input. show() changes the logical screen at once but
  // a wiped transition (results→null/main, title→main…) mounts the next one
  // only at the wipe's midpoint, and the following screen mounts while its
  // items are still invisible (entrance animation). Taps kept landing on
  // both: the closed results screen stayed live for ~0.4 s (a second tap
  // could REMATCH after MAIN MENU), and a tap begun there — or an impatient
  // tap on the not-yet-visible next screen — activated whatever item ended
  // up under the finger (LOADOUT, ONLINE…). A pending screen is inert; a
  // click needs a press that began on the same live screen, on a visible item.
  const pending=m=>!!(m._scr&&m.current!==m._scr.name);
  const closing=m=>{const el=m._scr?.el;if(!el||!pending(m))return;el.inert=true;el.style.pointerEvents='none';el.classList.add('is-closing');};
  // Delayed title/Mode transitions are owned by the transformed native Menus
  // methods. Do not override _titleGo here: that would create a second timer
  // owner and bypass their screen-generation and timer-identity checks.
  if(show)P.show=function(...args){
    if(retired.has(this))return;
    const result=show.apply(this,args);closing(this);return result;
  };
  if(nav)P._nav=function(dir){if(pending(this))return true;return nav.call(this,dir);};
  const visibleItem=(t,root)=>{
    let k=1;
    for(let e=t.closest?.('[data-nav]')||t;e&&e!==root.parentNode;e=e.parentElement){
      const o=+env.getComputedStyle?.(e)?.opacity;if(Number.isFinite(o))k*=o;
      if(e===root)break;
    }
    return k>0.6;
  };
  const guardInput=m=>{
    if(m._qualityInputGuard||!m.el?.addEventListener)return;
    m._qualityInputGuard=true;
    m.el.addEventListener('pointerdown',e=>{m._qualityPress={screen:m._scr?.el||null,target:e.target};},{capture:true,passive:true});
    m.el.addEventListener('click',e=>{
      const scr=m._scr;if(!scr?.el?.contains?.(e.target))return;
      const press=m._qualityPress;m._qualityPress=null;
      if(!pending(m)&&!scr.el.inert&&(!press||press.screen===scr.el)&&visibleItem(e.target,scr.el))return;
      e.stopImmediatePropagation();e.preventDefault();
    },true);
  };
  if(settings)P._scr_settings=function(...args){preparePreviewRoot(this.el,env);return settings.apply(this,args);};
  if(swap)P._swap=function(...args){
    clearPreviewRoot(this.el);guardInput(this);home(this);
    const result=swap.apply(this,args),r=ensure(this);
    if(active(this))r.arm();else stop(this,r);
    return result;
  };
  function stop(m,r){
    // A stopped owner is not a slow frame: the next tick starts a new cadence.
    m._ringFrameAt=NaN;
    if(m._raf){env.cancelAnimationFrame(m._raf);m._raf=0;}
    if(r?.timer!==null&&r?.timer!==undefined){env.clearTimeout(r.timer);r.timer=null;}
  }
  if(loop)P._loop=function(t){
    if(retired.has(this)||this._platformDriven||!lifecycle.active||env.document?.hidden||!active(this)){stop(this,records.get(this));return;}
    return loop.call(this,t);
  };
  function ensure(m){
    let r=records.get(m);if(r)return r;
    r={timer:null,off:null};records.set(m,r);
    const arm=()=>{if(r.timer===null&&!m._platformDriven&&!retired.has(m)&&active(m)&&lifecycle.active&&!env.document?.hidden)r.timer=env.setTimeout(watch,80);};
    const watch=()=>{
      r.timer=null;if(m._platformDriven||retired.has(m)||!lifecycle.active||env.document?.hidden||!active(m))return;
      const age=env.performance.now()-m._extTick;
      if(age>=80){
        // The external owner stopped. Hand animation back without a burst of
        // stale elapsed time or duplicate callbacks.
        m._lastT=Math.max(m._lastT,m._extTick);
        if(!m._raf)m._raf=env.requestAnimationFrame(m._loop);
      }else r.timer=env.setTimeout(watch,Math.max(1,80-age));
    };
    r.arm=arm;
    r.off=lifecycle.subscribe({
      suspend(){stop(m,r);},
      prepareResume(){stop(m,r);m._lastT=env.performance.now();m._extTick=-Infinity;},
      resume:arm,
    });
    return r;
  }
  P.setPlatformDriven=function(on){
    this._platformDriven=!!on;
    const r=ensure(this);stop(this,r);
    if(!on)r.arm();
  };
  P.update=function(dt){
    if(retired.has(this)||!lifecycle.active)return;
    const r=ensure(this);
    if(env.document?.hidden){stop(this,r);this._extTick=env.performance.now();return;}
    if(this._raf){env.cancelAnimationFrame(this._raf);this._raf=0;}
    if(!active(this)){stop(this,r);this._extTick=env.performance.now();return;}
    const result=update.call(this,dt);r.arm();return result;
  };
  P.dispose=function(...args){
    retired.add(this);clearPreviewRoot(this.el,true);const r=records.get(this);
    if(r){stop(this,r);r.off?.();records.delete(this);}
    return dispose.apply(this,args);
  };
}

methods.rangeMenu:
// Practice Range menus: a third card on PLAY (next to Turf War and Boss Battle) that starts the range directly, and the
// range's own pause screen (weapon, resets, travel, settings, leave) in place of the turf-war pause panel while a range
// match is running. Built with the menu system's own helpers (_btn, _panel, _header, _prompts, _bind) so it looks and
// navigates like every other screen (mouse, touch, keyboard and pad).
import { G } from '../../../src/core/ctx.js';
import { WEAPONS, WEAPON_ORDER, SUB, SPECIALS } from '../../../src/config.js';
import { h, splatSVG, safeCall, restartAnim } from '../../../src/ui/ui-util.js';
import { GLYPHS, SUB_ICONS, weaponIcon, specialIcon, padGlyph } from '../../../src/ui/ui-icons.js';
import { ZONES, ZONE_ORDER } from '../stage/zones.mjs';
import { L, isJa } from './strings.mjs';
import { RANGE_ID } from '../range-map.mjs';

const ART = new URL('../../../assets/stages/range-day.webp', import.meta.url).href;
const ART_SM = new URL('../../../assets/stages/range-day-sm.webp', import.meta.url).href;
const zoneName = (id) => (isJa ? ZONES[id].ja : ZONES[id].name);
const SUB_TEXT = {
  spawn: 'Where you started', lane: 'Paint distance · long shots · bomb throw', gallery: 'Range · damage at distance', paint: '400 m² floor · paint coverage',
  roller: 'Rolling · flicks · curves', dualies: 'Dodge rolls · fire after rolling', squid: 'Swim speed · turns · slopes',
  wall: 'Paint height · climbing · ledges', bomb: 'Throws · bounces · blast radius', special: 'Special radius · endurance targets',
};

function startRange(menus, card) {
  if (menus._starting) return;
  menus._starting = true;
  safeCall(() => menus.api.prepareMatch && menus.api.prepareMatch());   // still inside the tap (iOS motion permission)
  if (card) restartAnim(card, 'is-pick');
  menus._sfx('ui_confirm'); menus._sfx('splat_small', 0.06);
  menus._runWipe(() => {
    menus._starting = false;
    safeCall(() => menus.api.startMatch && menus.api.startMatch({ mapId: RANGE_ID }));
    if (menus.current === 'mode') menus.show(null, { instantLeave: true });
  });
}

function rangeCard(menus) {
  const img = h('img', { class: 'iw-mode__img', alt: '', draggable: 'false' });
  img.addEventListener('error', () => img.remove(), { once: true });
  img.src = ART;
  const target = h('span', { class: 'iwr-mode__target' }, h('i'), h('i'), h('i'));
  const c = h('button', { class: 'iw-mode iw-mode--range iw-in iw-in--pop', style: { '--tilt': '1.1deg' } },
    h('span', { class: 'iw-mode__art' }, img, h('i', { class: 'iw-mode__tint' }),
      h('span', { class: 'iw-mode__splat', html: splatSVG({ seed: 77, fill: 'var(--mc)', r: 58, arms: 9, drops: 5 }) }),
      h('span', { class: 'iw-mode__hero is-range' }, target), h('i', { class: 'iw-mode__glare' })),
    h('span', { class: 'iw-mode__kicker' }, L('TRAINING')),
    h('span', { class: 'iw-mode__tape' }, h('span', { class: 'iw-display' }, L('PRACTICE RANGE'))),
    h('span', { class: 'iw-mode__blurb' }, L('Range, damage, paint, movement, bombs and specials — measured on a world-scale grid.')),
    h('span', { class: 'iw-mode__chips' }, [[GLYPHS.users, L('SOLO')], [GLYPHS.map, L('9 TEST ZONES')], [GLYPHS.clock, L('NO TIMER')]].map(([ic, t]) => h('span', { class: 'iw-chip' }, h('i', { html: ic }), t))),
    h('span', { class: 'iw-mode__go' }, h('i', { html: GLYPHS.play }), 'START'));
  c.dataset.cur = 'own';
  menus._fx(c, { tilt: 7 });
  menus._bind(c, { id: 'mode-range', accept: () => startRange(menus, c) });
  return c;
}

function decorateMode(menus, scr) {
  const row = scr.el.querySelector('.iw-modesel__row');
  const boss = scr.el.querySelector('.iw-mode--boss');
  if (!row || !boss) return scr;
  const card = rangeCard(menus);
  row.appendChild(card);
  row.classList.add('has-range');
  const bg = scr.el.querySelector('.iw-ss__bg');
  const setBg = () => {
    if (!bg) return;
    const im = h('img', { class: 'iw-ss__bgimg', alt: '', draggable: 'false' });
    im.addEventListener('error', () => im.remove(), { once: true });
    im.src = ART_SM;
    const olds = [...bg.children]; bg.appendChild(im);
    requestAnimationFrame(() => requestAnimationFrame(() => im.classList.add('is-on')));
    setTimeout(() => olds.forEach((o) => o.remove()), 900);
  };
  const onFocus = scr.onFocus, onNav = scr.onNav;
  scr.onFocus = (f) => {
    if (f === card) { if (scr.el.dataset.mode !== 'range') { scr.el.dataset.mode = 'range'; setBg(); } return; }
    // leaving the range card: let the native handler swap the art back (it only acts when the mode changes)
    if (scr.el.dataset.mode === 'range' && f && f._mode) scr.el.dataset.mode = '';
    return onFocus?.(f);
  };
  scr.onNav = (dir) => {
    const f = menus._focus;
    if (f === boss && dir === 'right') { menus._moveFocus(card, dir); return true; }
    if (f === card) {
      if (dir === 'left') { menus._moveFocus(boss, dir); return true; }
      if (dir === 'right' || dir === 'up' || dir === 'down') { menus._bump(card, dir); return true; }
    }
    return onNav?.(dir);
  };
  return scr;
}

// ------------------------------------------------------------------ the range pause screen
// One panel, three tabs: TOOLS (resets, refill, moving targets), TRAVEL (zones) and WEAPON (all 160 mains, filtered by
// class). The full weapon list used to sit on top and push resets and travel several screens down. Q / E (LB / RB) or a
// tap switch tabs; the last tab is remembered while the game runs.
const TABS = ['tools', 'travel', 'weapon'];
let lastTab = 'travel';
const classKey = (W) => String((W && (W.class || W.kind)) || '').toLowerCase();

function rangePause(menus) {
  const session = G.match?.range;
  const items = [
    { id: 'resume', label: L('RESUME'), icon: GLYPHS.play, cls: 'iw-btn--menu iw-btn--primary', accept: () => menus._resume(), sound: null },
    { id: 'settings', label: L('SETTINGS'), icon: GLYPHS.gear, cls: 'iw-btn--menu', accept: () => menus._go('settings') },
    { id: 'quit', label: L('LEAVE RANGE'), icon: GLYPHS.exit, cls: 'iw-btn--menu iw-btn--danger', accept: () => menus._openModal({
      title: L('LEAVE THE RANGE?'), danger: true, text: L('You will head back to the lobby.'),
      buttons: [
        { label: L('STAY'), accept: () => menus._closeModal(), sound: null },
        { label: L('LEAVE'), cls: 'iw-btn--danger', sound: 'ui_confirm', accept: () => {
          menus._closeModal(true);
          safeCall(() => menus.api.quitMatch && menus.api.quitMatch());
          if (menus.current === 'pause') menus.show('main', { wipe: true });
        } },
      ],
    }) },
  ];
  const tilts = [-1.8, 1.2, -1];
  const btns = items.map((it, i) => { const b = menus._btn({ ...it, tilt: tilts[i] }); b.classList.add('iw-in', 'iw-in--left'); return b; });
  const act = (fn) => () => { menus._sfx('ui_confirm'); safeCall(fn); menus._resume(); };

  // ---- the equipped weapon, always in view
  const cur = session?.local?.weaponId;
  const CW = WEAPONS[cur];
  const curSub = CW && SUB[CW.sub], curSp = CW && SPECIALS[CW.special];
  const current = h('div', { class: 'iwr-cur' },
    h('span', { class: 'iwr-cur__icon', html: weaponIcon(cur) }),
    h('span', { class: 'iwr-cur__txt' }, h('small', null, L('EQUIPPED')), h('b', null, CW ? CW.name : ''),
      h('span', { class: 'iwr-cur__kit' },
        curSub ? h('span', null, h('i', { html: SUB_ICONS[CW.sub] || SUB_ICONS.bomb }), curSub.name) : null,
        curSp ? h('span', { class: 'is-sp' }, h('i', { html: specialIcon(CW.special) }), curSp.name) : null)));

  // ---- WEAPON: class filter + chips (the equipped one is marked); choosing one switches and resumes
  const wchips = WEAPON_ORDER.map((id) => {
    const W = WEAPONS[id];
    const b = h('button', { class: 'iwr-wchip' + (id === cur ? ' is-on' : ''), title: W.name }, h('span', { class: 'iwr-wchip__icon', html: weaponIcon(id) }), h('b', null, W.name), h('small', null, W.class || ''));
    b.dataset.cat = classKey(W);
    menus._fx(b); menus._bind(b, { id: 'w-' + id, accept: act(() => session?.setWeapon(id)) });
    return b;
  });
  const cats = [];
  for (const b of wchips) {
    const c = cats.find((x) => x.key === b.dataset.cat);
    if (c) c.n++; else cats.push({ key: b.dataset.cat, label: b.querySelector('small').textContent || b.dataset.cat, n: 1 });
  }
  const wgrid = h('div', { class: 'iwr-wchips' }, wchips);
  const filters = [{ key: 'all', label: L('ALL'), n: wchips.length }, ...cats].map((c) => {
    const b = h('button', { class: 'iwr-filter' + (c.key === 'all' ? ' is-on' : '') }, h('span', null, c.label), h('small', null, String(c.n)));
    b.dataset.cat = c.key;
    menus._bind(b, { id: 'wf-' + (c.key || 'other'), type: 'tab', accept: () => { menus._sfx('ui_toggle'); setCat(c.key); } });
    return b;
  });
  const setCat = (key) => {
    for (const f of filters) f.classList.toggle('is-on', f.dataset.cat === key);
    for (const b of wchips) b.hidden = key !== 'all' && b.dataset.cat !== key;
    body.scrollTop = 0;
  };

  // ---- TOOLS
  const resets = [
    ['resetPaint', L('RESET PAINT'), 'R', () => session?.resetPaint()],
    ['resetDummies', L('RESET TARGETS'), 'T', () => session?.resetTargets()],
    ['spawn', L('RETURN TO START'), 'G', () => session?.travel('spawn')],
    ['inkCourse', L('INK COURSE'), '', () => session?.inkCourse()],
    ['resupply', L('REFILL'), '', () => session?.resupply()],
  ].map(([id, label, key, fn]) => {
    const b = h('button', { class: 'iwr-rbtn' }, h('b', null, label), key ? h('kbd', null, key) : null);
    menus._fx(b); menus._bind(b, { id: 'r-' + id, accept: act(fn) });
    return b;
  });
  const moving = h('button', { class: 'iwr-rbtn iwr-toggle' + (session?.movingTargets ? ' is-on' : '') }, h('b', null, L('MOVING TARGETS')), h('span', { class: 'iwr-toggle__v' }, session?.movingTargets ? L('ON') : L('OFF')));
  menus._fx(moving);
  menus._bind(moving, { id: 'r-moving', accept: () => {
    menus._sfx('ui_toggle');
    const on = !session?.movingTargets; session?.setMovingTargets(on);
    moving.classList.toggle('is-on', on); moving.querySelector('.iwr-toggle__v').textContent = on ? L('ON') : L('OFF');
  } });

  // ---- TRAVEL
  const travel = ['spawn', ...ZONE_ORDER].map((id) => {
    const z = id === 'spawn' ? null : ZONES[id];
    const b = h('button', { class: 'iwr-zbtn', style: { '--zc': z ? z.accent : '#35405a' } },
      h('span', { class: 'iwr-zbtn__l' }, z ? z.letter : '⌂'),
      h('span', { class: 'iwr-zbtn__t' }, h('b', null, z ? zoneName(id) : L('Spawn deck')), h('small', null, L(SUB_TEXT[id]))));
    menus._fx(b); menus._bind(b, { id: 'z-' + id, accept: act(() => session?.travel(id)) });
    return b;
  });

  const secs = {
    tools: h('div', { class: 'iwr-pause__sec', 'data-tab': 'tools' }, h('div', { class: 'iwr-rbtns' }, resets, moving),
      h('div', { class: 'iwr-pause__hint' }, L('R · T · G also work during play.'))),
    travel: h('div', { class: 'iwr-pause__sec', 'data-tab': 'travel' },
      h('div', { class: 'iwr-pause__hint' }, L('Choose a zone to jump straight to its reference stand.')), h('div', { class: 'iwr-zbtns' }, travel)),
    weapon: h('div', { class: 'iwr-pause__sec', 'data-tab': 'weapon' }, h('div', { class: 'iwr-filters' }, filters), wgrid),
  };
  const body = h('div', { class: 'iwr-pause__body' }, TABS.map((k) => secs[k]));
  const tabInfo = { tools: [GLYPHS.reset, L('RESETS')], travel: [GLYPHS.map, L('TRAVEL')], weapon: [GLYPHS.target || GLYPHS.star, L('WEAPON'), String(wchips.length)] };
  const tabs = TABS.map((k) => {
    const [icon, label, count] = tabInfo[k];
    const b = h('button', { class: 'iwr-tab' }, h('i', { html: icon }), h('span', null, label), count ? h('small', null, count) : null);
    b.dataset.tab = k;
    menus._fx(b); menus._bind(b, { id: 'r-tab-' + k, type: 'tab', accept: () => { menus._sfx('ui_toggle'); setTab(k); } });
    return b;
  });
  let tab = TABS.includes(lastTab) ? lastTab : 'travel';
  const setTab = (k, { focus = false } = {}) => {
    tab = lastTab = k;
    for (const t of tabs) t.classList.toggle('is-on', t.dataset.tab === k);
    for (const key of TABS) secs[key].hidden = key !== k;
    panel.dataset.tab = k;
    body.scrollTop = 0;
    if (k === 'weapon') {
      // open on the equipped weapon's row
      const on = wchips.find((b) => b.classList.contains('is-on') && !b.hidden);
      if (on) requestAnimationFrame(() => { if (on.isConnected && body.scrollHeight > body.clientHeight) body.scrollTop = Math.max(0, on.offsetTop - body.offsetTop - 12); });
    }
    if (focus) {
      const f = menus._focus;
      if (f && panel.contains(f) && !tabs.includes(f)) menus._setFocus(tabs.find((t) => t.dataset.tab === k), { snap: true });
    }
  };
  const panel = menus._panel('iwr-pause iw-panel--flat iw-in iw-in--right',
    h('div', { class: 'iwr-pause__top' }, current, h('div', { class: 'iwr-tabs', role: 'tablist' }, tabs)),
    body,
    h('div', { class: 'iwr-pause__foot' }, L('Every mark is a world coordinate: 1 m on the floor = 1.000 game unit.')));
  setTab(tab);
  // Pointer-over precedes Menus' pointerenter focus (and mousemove). Keep
  // that target stable through its press instead of scrolling it on hover.
  let pointerTarget = null;
  panel.addEventListener('pointerover', e => { pointerTarget = e.target.closest?.('[data-nav]') || null; }, true);
  panel.addEventListener('pointerout', e => { if (!pointerTarget?.contains(e.relatedTarget)) pointerTarget = null; }, true);
  const el = h('div', { class: 'iw-screen iw-pause iwr-pausescr' },
    h('div', { class: 'iw-dimbg' }),
    menus._header(L('PRACTICE RANGE'), { back: false, sub: 'ZEVANT INK LAB' }),
    h('nav', { class: 'iw-pause__menu iwr-pause__menu' }, btns),
    panel,
    menus._prompts([['Enter', 'A', 'Select'], [['Q', 'E'], null, L('Tabs')], ['Esc', 'B', 'Back']]));
  const tabHint = el.querySelector('.iw-prompts').children[1]?.querySelector('.iw-padg');
  if (tabHint) tabHint.innerHTML = padGlyph('LB') + padGlyph('RB');
  return {
    el, initial: btns[0],
    onBack: () => menus._resume(),
    onNav: (dir) => {
      if (dir !== 'tab_prev' && dir !== 'tab_next') return false;
      const i = TABS.indexOf(tab);
      setTab(TABS[(i + (dir === 'tab_next' ? 1 : TABS.length - 1)) % TABS.length], { focus: true });
      menus._sfx('ui_toggle');
      return true;
    },
    // the panel scrolls on short screens: keep the keyboard / pad focus in view
    // Hover/click focus must not scroll the target out from under the pointer.
    onFocus: (f) => {
      const pointer = menus._input === 'touch' || pointerTarget === f;
      if (!pointer && f && panel.contains(f)) safeCall(() => f.scrollIntoView({ block: 'nearest', inline: 'nearest' }));
    },
  };
}

export function installRangeMenus(Menus) {
  const P = Menus.prototype;
  const mode = P._scr_mode, pause = P._scr_pause;
  P._scr_mode = function (...args) { return decorateMode(this, mode.apply(this, args)); };
  P._scr_pause = function (...args) {
    if (G.match && !G.match.attract && G.match.range) return rangePause(this);
    return pause.apply(this, args);
  };
}

methods.rangeHud:
// Practice Range HUD: a compact telemetry strip where the turf-war roster/timer would be, a target card that appears
// while you are hitting targets, floating damage numbers over the targets, the pad prompt and short toasts.
// Lives inside the game HUD element (so it hides / shows with it) and is removed with the session.
// Everything it shows is read from actor state or the game's own events — it computes nothing about weapons.
import * as THREE from 'three';
import { G } from '../../../src/core/ctx.js';
import { WEAPONS, PLAYER } from '../../../src/config.js';
import { h } from '../../../src/ui/ui-util.js';
import { weaponIcon } from '../../../src/ui/ui-icons.js';
import { ZONES } from '../stage/zones.mjs';
import { L, isJa } from './strings.mjs';

const _p = new THREE.Vector3();
const PAD_TEXT = { resetPaint: 'RESETTING PAINT', resetDummies: 'RESETTING TARGETS', inkCourse: 'INKING THE SWIM COURSE', resupply: 'RESUPPLY' };
const fmt = (v, d = 1) => (Number.isFinite(v) ? v.toFixed(d) : '—');
const zoneLabel = (id) => (id && ZONES[id] ? `${ZONES[id].letter ? ZONES[id].letter + ' · ' : ''}${isJa ? ZONES[id].ja : ZONES[id].name}` : '—');
const setText = (el, text) => { if (el.textContent !== text) el.textContent = text; };

export class RangeHud {
  constructor(session) {
    this.s = session;
    const host = G.hud?.el || document.getElementById('ui-root');
    this.wIcon = h('span', { class: 'iwr-tel__wicon' });
    this.wName = h('b', { class: 'iwr-tel__wname' });
    this.speed = h('b', { class: 'iwr-num' }, '0.0');
    this.zone = h('span', { class: 'iwr-tel__zone' });
    this.measure = h('b', { class: 'iwr-num' });
    this.measureLbl = h('small');
    this.measureBox = h('span', { class: 'iwr-tel__cell iwr-tel__measure' }, this.measureLbl, h('span', null, this.measure, h('i', null, 'm')));
    this.paintBox = h('span', { class: 'iwr-tel__cell iwr-tel__paint' });
    this.tel = h('div', { class: 'iwr-tel' },
      h('span', { class: 'iwr-tel__cell iwr-tel__weapon' }, this.wIcon, this.wName),
      h('span', { class: 'iwr-tel__cell' }, h('small', null, L('SPEED')), h('span', null, this.speed, h('i', null, 'm/s'))),
      h('span', { class: 'iwr-tel__cell iwr-tel__zonecell' }, h('small', null, L('ZONE')), this.zone),
      this.measureBox, this.paintBox);
    // target card
    this.cName = h('b', { class: 'iwr-card__name' });
    this.cLast = h('b', { class: 'iwr-num iwr-card__big' });
    this.cFrom = h('span', { class: 'iwr-card__from' });
    this.cCombo = h('b', { class: 'iwr-num' });
    this.cHits = h('b', { class: 'iwr-num' });
    this.cSplat = h('span', { class: 'iwr-card__splat' });
    this.cHp = h('i');
    this.card = h('div', { class: 'iwr-card' },
      h('div', { class: 'iwr-card__head' }, h('span', { class: 'iwr-card__tag' }, L('TARGET')), this.cName),
      h('div', { class: 'iwr-card__row' }, h('div', null, h('small', null, L('LAST HIT')), this.cLast), this.cFrom),
      h('div', { class: 'iwr-card__row iwr-card__row--3' },
        h('div', null, h('small', null, L('COMBO')), this.cCombo),
        h('div', null, h('small', null, L('HITS')), this.cHits),
        this.cSplat),
      h('div', { class: 'iwr-card__hp' }, this.cHp));
    this.nums = h('div', { class: 'iwr-nums' });
    this.prompt = h('div', { class: 'iwr-prompt' }, h('b'), h('span', { class: 'iwr-prompt__bar' }, h('i')));
    this.toastEl = h('div', { class: 'iwr-toast' });
    this.keys = h('div', { class: 'iwr-keys' },
      ...[['R', 'Reset paint'], ['T', 'Reset targets'], ['G', 'Back to start']].map(([k, t]) => h('span', null, h('kbd', null, k), L(t))));
    this.root = h('div', { class: 'iwr-hud' }, this.nums, this.tel, this.card, this.prompt, this.toastEl, this.keys);
    host.appendChild(this.root);
    this._L = {};
    this._cardT = 99; this._toastT = 99;
    this._float = [];
    this.root.classList.toggle('is-touch', document.documentElement.classList.contains('iw-touch-ui'));
  }

  welcome() { this.toast(L('WELCOME TO THE RANGE'), 2.6, true); }
  toast(text, life = 1.8, big = false) {
    this.toastEl.textContent = text;
    this.toastEl.classList.toggle('is-big', !!big);
    this.toastEl.classList.remove('is-on'); void this.toastEl.offsetWidth; this.toastEl.classList.add('is-on');
    this._toastT = 0; this._toastLife = life;
  }
  padPrompt(pad, k) {
    const key = pad ? pad.id : '';
    if (key !== this._L.pad) {
      this._L.pad = key;
      this.prompt.classList.toggle('is-on', !!pad);
      if (pad) this.prompt.firstChild.textContent = pad.kind === 'weapon'
        ? `${L('SWITCHING WEAPON')} · ${WEAPONS[pad.weapon].name}` : L(PAD_TEXT[pad.kind] || pad.kind);
    }
    if (pad) this.prompt.querySelector('i').style.transform = `scaleX(${Math.max(0, Math.min(1, k)).toFixed(3)})`;
  }
  damageNumber(target, amount, splat) {
    const el = h('span', { class: 'iwr-dmg' + (splat ? ' is-splat' : '') + (target.rangeTarget.kind === 'endurance' ? ' is-endure' : '') }, splat ? 'SPLAT!' : fmt(amount, 1));
    this.nums.appendChild(el);
    this._float.push({ el, target, t: 0, life: splat ? 1.1 : 0.9, dx: (Math.random() - 0.5) * 30 });
    if (this._float.length > 24) { const o = this._float.shift(); o.el.remove(); }
    this._cardT = 0;
  }

  update(dt) {
    const tel = this.s.telemetry();
    if (!tel) return;
    const L0 = this._L;
    if (tel.weapon !== L0.weapon) {
      L0.weapon = tel.weapon;
      const W = WEAPONS[tel.weapon];
      this.wIcon.innerHTML = weaponIcon((W && W.kind) || tel.weapon);
      this.wName.textContent = W ? W.name : tel.weapon;
    }
    const sp = fmt(tel.speed, 1);
    if (sp !== L0.sp) { L0.sp = sp; this.speed.textContent = sp; }
    if (tel.zone !== L0.zone) {
      L0.zone = tel.zone;
      this.zone.textContent = zoneLabel(tel.zone);
      this.tel.style.setProperty('--zc', tel.zone ? ZONES[tel.zone].accent : '#35405a');
    }
    const m = tel.measure;
    this.measureBox.classList.toggle('is-off', !m);
    if (m) {
      const lbl = m.kind === 'wall' ? L('FROM WALL') : L('DOWNRANGE');
      if (lbl !== L0.mlbl) { L0.mlbl = lbl; this.measureLbl.textContent = lbl; }
      const v = fmt(m.value, 1);
      if (v !== L0.mv) { L0.mv = v; this.measure.textContent = v; }
    }
    const inPaint = tel.zone === 'paint';
    this.paintBox.classList.toggle('is-off', !inPaint);
    if (inPaint) {
      const ps = this.s.paintStats();
      if (ps) {
        const txt = `${fmt(ps.own, 1)} m² · ${fmt((ps.own / ps.total) * 100, 1)} %`;
        if (txt !== L0.paint) { L0.paint = txt; this.paintBox.innerHTML = ''; this.paintBox.append(h('small', null, L('PAINTED')), h('span', null, txt)); this.paintBox.title = L('of the 400 m² test floor'); }
      }
    }
    // target card: the target you hit last, until 4 s after the last hit
    this._cardT += dt;
    const last = this.s.last;
    const show = !!last && this._cardT < 4;
    this.card.classList.toggle('is-on', show);
    if (show) {
      const a = last.target, t = a.rangeTarget, c = t.combo;
      if (L0.cname !== a.name) { L0.cname = a.name; this.cName.textContent = a.name; this.card.classList.toggle('is-endure', t.kind === 'endurance'); }
      setText(this.cLast, fmt(last.amount, 1));
      setText(this.cFrom, last.dist != null ? `${L('FROM')} ${fmt(last.dist, 1)} m` : '');
      setText(this.cCombo, c ? fmt(c.total, 1) : '—');
      setText(this.cHits, c ? String(c.hits) : '—');
      setText(this.cSplat, t.kind === 'endurance' ? `${L('ENDURANCE')} · ${L('never pops')}`
        : c && c.done ? `${L('SPLAT IN')} ${c.hits} · ${fmt(c.splatT, 2)} s` : '');
      const hp = t.kind === 'endurance' ? 1 : Math.max(0, Math.min(1, a.hp / PLAYER.hp));
      const transform = `scaleX(${hp.toFixed(3)})`;
      // CSSOM normalizes numeric spelling. Keep its written form as well as
      // the requested transform so external changes still get repaired.
      if (L0.cardHpTransform !== transform || this.cHp.style.transform !== L0.cardHpActual) {
        this.cHp.style.transform = transform;
        L0.cardHpTransform = transform; L0.cardHpActual = this.cHp.style.transform;
      }
    }
    // floating numbers over the targets
    const cam = G.camera, W = innerWidth, H = innerHeight;
    for (let i = this._float.length - 1; i >= 0; i--) {
      const f = this._float[i];
      f.t += dt;
      if (f.t > f.life) { f.el.remove(); this._float.splice(i, 1); continue; }
      _p.copy(f.target.pos); _p.y += PLAYER.height + 0.35 + f.t * 0.6;
      _p.project(cam);
      if (!Number.isFinite(_p.x) || !Number.isFinite(_p.y) || !Number.isFinite(_p.z) || _p.z < -1 || _p.z > 1) {
        f.el.style.opacity = '0'; continue;
      }
      const x = (_p.x * 0.5 + 0.5) * W + f.dx * f.t, y = (-_p.y * 0.5 + 0.5) * H;
      const k = f.t / f.life;
      f.el.style.opacity = String(Math.min(1, (1 - k) * 2.4));
      f.el.style.transform = `translate(${x.toFixed(1)}px, ${y.toFixed(1)}px) translate(-50%, -50%) scale(${(1 + 0.35 * Math.max(0, 0.15 - f.t) / 0.15).toFixed(3)})`;
    }
    this._toastT += dt;
    if (this._toastT > (this._toastLife || 1.8) && this.toastEl.classList.contains('is-on')) this.toastEl.classList.remove('is-on');
  }

  clearTargetFeedback() {
    for (const f of this._float) f.el.remove();
    this._float.length = 0; this._cardT = 99;
    this.card.classList.remove('is-on');
  }
  dispose() { this.clearTargetFeedback(); this.root.remove(); }
}

methods.bossNum:
_addNum(w, dmg, weak, now) {
  const S = this.S;
  let c = S.combo;
  if (!c || c.out || now - c.last > 0.45) {
    const el = h('div', { class: 'iw-bnum' }, h('b'));
    this.numLayer.appendChild(el);
    c = S.combo = { el, txt: el.firstChild, sum: 0, w: { ...w }, last: now, born: now, weak: false, out: false, jx: (Math.random() - 0.5) * 2 };
    S.nums.push(c);
    while (S.nums.length > 6) { const o = S.nums.shift(); o.el.remove(); }
  }
  c.sum += dmg; c.last = now;
  c.w.x += (w.x - c.w.x) * 0.35; c.w.y += (w.y - c.w.y) * 0.35; c.w.z += (w.z - c.w.z) * 0.35;
  if (weak && !c.weak) { c.weak = true; c.el.classList.add('is-weak'); }
  c.txt.textContent = fmtInt(c.sum);
  c.el.style.setProperty('--s', clamp(0.85 + Math.log10(Math.max(1, c.sum)) * 0.16 + (c.weak ? 0.2 : 0), 0.85, 1.6).toFixed(3));
  restartAnim(c.el, 'is-bump');
}

methods.slider:
_slider(row, value) {
  const { key, min, max, step, fmt } = row;
  let v = +value;
  const fill = h('span', { class: 'iw-slider__fill' });
  const knob = h('span', { class: 'iw-slider__knob' });
  const def = DEFAULT_SETTINGS[key];
  const mark = def != null ? h('span', { class: 'iw-slider__def', style: { '--d': clamp((def - min) / (max - min)).toFixed(4) }, title: 'Default' }) : null;
  const track = h('span', { class: 'iw-slider__track iw-noclick' }, mark, fill, knob);
  const val = h('span', { class: 'iw-slider__val' });
  const el = h('span', { class: 'iw-slider' }, track, val);
  const render = () => {
    el.style.setProperty('--t', clamp((v - min) / (max - min)).toFixed(4));
    val.textContent = fmt(v);
  };
  const bump = () => { if (val.animate && !prefersReducedMotion()) val.animate([{ scale: 1.22, translate: '0 -2px' }, { scale: 1, translate: '0 0' }], { duration: 260, easing: 'cubic-bezier(.34,1.56,.64,1)' }); };
  const set = (nv, src) => {
    nv = clamp(Math.round((nv - min) / step) * step + min, min, max);
    nv = +nv.toFixed(4);
    if (nv === v) { if (src === 'key') { this._sfx('ui_error', 0.2); restartAnim(el, 'is-edge'); } return; }
    v = nv; render();
    this._setSetting(key, v);
    this._sfx('ui_slider', 0.05);
    bump();
    if (src === 'key') restartAnim(knob, 'is-bump');
  };
  let drag = null;
  const endDrag = () => {
    if (!drag) return;
    const { id, move, end } = drag; drag = null;
    el.classList.remove('is-drag');
    track.removeEventListener('pointermove', move);
    for (const type of ['pointerup', 'pointercancel', 'lostpointercapture']) track.removeEventListener(type, end);
    window.removeEventListener('blur', endDrag);
    try { if (track.hasPointerCapture(id)) track.releasePointerCapture(id); } catch (err) { /* already released */ }
  };
  track.addEventListener('pointerdown', (e) => {
    if (drag || e.button !== 0) return;
    const r = track.getBoundingClientRect();
    if (!(r.width > 0)) return;
    e.preventDefault(); e.stopPropagation();
    const focusRow = track.closest?.('[data-nav]');
    if (focusRow) this._setFocus(focusRow);
    const id = e.pointerId;
    const move = (ev) => {
      if (ev.pointerId === id) set(min + clamp((ev.clientX - r.left) / r.width) * (max - min), 'mouse');
    };
    const end = (ev) => { if (ev.pointerId === id) endDrag(); };
    drag = { id, move, end };
    track.addEventListener('pointermove', move);
    for (const type of ['pointerup', 'pointercancel', 'lostpointercapture']) track.addEventListener(type, end);
    window.addEventListener('blur', endDrag);
    try { track.setPointerCapture(id); } catch (err) { /* synthetic events */ }
    el.classList.add('is-drag'); move(e);
  });
  render();
  let lastAdj = 0, accel = 1;
  return {
    el,
    adjust: (d) => {
      const t = performance.now();
      accel = t - lastAdj < 110 ? Math.min(accel + 0.35, 4) : 1;
      lastAdj = t;
      set(v + d * step * Math.floor(accel), 'key');
    },
    refresh: (nv) => { if (v !== +nv) { v = +nv; render(); } },
    destroy: endDrag,
  };
}

methods.lobbyTick:
  // countdown → GO → super-jumps → hand over
  const L = S.launching;
  if (L) {
    if (net && net.state === 'lobby' && L.t > 0.3 && !L.fired) { // the start was called off
      S.launching = null; el.classList.remove('is-starting'); countdown.classList.remove('is-on'); safeCall(L.done); return;
    }
    L.t += dt;
    const T = L.t;
    if (T >= 0.35 && T < 1.2) cdStep(3); else if (T >= 1.2 && T < 2.05) cdStep(2); else if (T >= 2.05 && T < 2.9) cdStep(1);
    else if (T >= 2.9 && !L.fired) {
      cdStep(0); L.fired = true;
      const dur = sc && sc.lobbyLaunch ? sc.lobbyLaunch() : 0;
      L.end = T + Math.max(0.5, Math.min(1.3, dur)) + 0.1;
      if (!reduced) this._burstAt(cdNum, { count: 22, dist: 16, size: 2.2, ring: true, color: 'var(--self)' });
    }
    if (L.fired && T >= L.end && !L.handed) { L.handed = true; safeCall(L.done); }
  }
},

