  _move(e) {
    if (guardPortraitPointer(this,e)) return;
    const p = this._ptr.get(e.pointerId);
    if (this.editing) { this._editMove(e); return; }
    if (e.pointerId === this._stick.id) { stop(e); this._stickMove(e); return; }
    if (!p) return;
    stop(e);
