  _jump(i, me) {
    const p = this.pins[i];
    if (!me || !this.on || this.k < 0.7 || !p || me !== G.match?.local || G.match?.attract ||
        (i < 3 && (!p.target || !G.actors?.includes(p.target) || p.target === me || p.target.team !== me.team))) return;
    if (!(me && G.match?.controller?.a === me ? G.match.controller.canRequestMapJump() : !!me?.canSuperJump?.())) { G.audio?.play?.('ui_error', { volume: 0.5 }); return; }
    let ok = false;
    if (i === 3) { const pad = G.level?.homeSuperJumpPoints?.[me.team] || G.level?.spawnPads?.[me.team]; ok = pad ? (me && G.match?.controller?.a === me ? G.match.controller.requestMapJump(pad.clone()) : me.superJump(pad.clone())) : false; }
    else if (i >= 4 && i < this.pins.length - 1) ok = p.bubblerTarget ? (me && G.match?.controller?.a === me ? G.match.controller.requestMapBubblerJump(p.bubblerTarget) : !!me.superJumpToBubbler?.(p.bubblerTarget)) : false;
    else if (p.target && p.target.alive && (!p.target.superJumpState || hasCommittedSuperJumpDestination(p.target))) ok = me && G.match?.controller?.a === me ? G.match.controller.requestMapJump(p.target) : me.superJump(p.target);
    this._flash(i);
    G.audio?.play?.(ok ? 'ui_confirm' : 'ui_error', { volume: 0.55 });
  }

  _flash(i) {
    const el = this.pins[i]?.el; if (!el) return;
    el.classList.remove('is-press'); void el.offsetWidth; el.classList.add('is-press');
  }

  _head() {
    const m = G.game?.mapDef;
    this.title.textContent = (m?.name || t('Stage')).toUpperCase();
    this.when.textContent = t(G.game?.time === 'dusk' ? 'DUSK' : 'DAY');
    const dev = G.input?.lastDevice;
    const S = (x) => `<span>${esc(t(x))}</span>`;
    this.foot.innerHTML = dev === 'pad'
      ? richText('Right stick to point · D-pad selects allies/base · LB/RB cycle Bubblers · A confirms · release VIEW to close')
      : dev === 'touch'
        ? S('Tap a pin to Super Jump · tap MAP to close')
      : `${keycap('1')}${keycap('2')}${keycap('3')} ${S('Super Jump to a teammate')} ${keycap('4')} ${S('Base')} ${keycap('5')}–${keycap('9')} ${S('Bubbler')} <em>·</em> ${S('Point + click a pin')} <em>·</em> ${S('release')} ${keycap('TAB')}`;
  }
}

